def solve(payload):
    import re
    files, user = payload["files"], payload["user"]
    if any(not re.fullmatch(r"[0-7]{3,4}", f["mode"]) for f in files):
        return {"error": "invalid_mode"}
    entries = []
    for f in files:
        mode = int(f["mode"], 8)
        shift = 6 if user["uid"] == f["owner_uid"] else 3 if f["group_gid"] in user["groups"] else 0
        bits = (mode >> shift) & 7
        effective = "".join(letter if bits & bit else "-" for letter, bit in (("r", 4), ("w", 2), ("x", 1)))
        risks = []
        if mode & 0o002 and not (f["directory"] and mode & 0o1000):
            risks.append("world_writable")
        if mode & 0o4000:
            risks.append("setuid")
        if mode & 0o2000:
            risks.append("setgid")
        entries.append({"path": f["path"], "effective": effective, "risks": risks})
    return {"entries": entries}

